%% Compare MCCAR loadings between adjacent DEP symptom groups
% Required input:
%   DEP_group_loadings.mat generated by extract_DEP_group_loadings.m
%
% Planned independent-group comparisons:
%   1. no_or_minimal vs mild
%   2. mild          vs moderate
%   3. moderate      vs high
%
% For every modality and component, this script performs a two-sided
% Welch two-sample t-test. The primary Benjamini-Hochberg FDR correction
% is performed separately for each modality x planned-comparison family.
% Each family therefore contains 80 component tests. With 3 modalities
% and 3 comparisons, there are 9 independent FDR families.
%
% Outputs:
%   DEP_loading_group_comparisons.mat
%   DEP_loading_group_comparisons.xlsx

clearvars;
clc;

%% -------------------------- Configuration -----------------------------
projectRoot = fileparts(mfilename('fullpath'));
inputFile = fullfile(projectRoot, 'DEP_group_loadings.mat');
outputMat = fullfile(projectRoot, 'DEP_loading_group_comparisons.mat');
outputXlsx = fullfile(projectRoot, 'DEP_loading_group_comparisons.xlsx');

alpha = 0.05;

% IMPORTANT: These labels must follow the order of A{1}, A{2}, A{3} used
% in the MCCAR analysis. Edit them if your actual modality order differs.
modalityNames = ["fMRI", "dMRI", "sMRI"];

comparisonGroupA = ["no_or_minimal", "mild",     "moderate"];
comparisonGroupB = ["mild",          "moderate", "high"];
comparisonNames = comparisonGroupA + "_vs_" + comparisonGroupB;

%% ---------------------------- Load data -------------------------------
assert(isfile(inputFile), 'Input MAT file does not exist:\n%s', inputFile);
S = load(inputFile, 'DEP');
assert(isfield(S, 'DEP'), 'Variable DEP was not found in:\n%s', inputFile);
DEP = S.DEP;

requiredGroups = ["no_or_minimal", "mild", "moderate", "high"];
for g = 1:numel(requiredGroups)
    assert(isfield(DEP.groups, char(requiredGroups(g))), ...
        'DEP.groups.%s was not found.', requiredGroups(g));
end

nModality = numel(DEP.groups.no_or_minimal.loadings);
assert(numel(modalityNames) == nModality, ...
    ['modalityNames contains %d labels, but the loadings contain %d ' ...
     'modalities. Please correct modalityNames.'], ...
    numel(modalityNames), nModality);

nComponent = size(DEP.groups.no_or_minimal.loadings{1}, 2);

% Validate all loading matrices before any testing.
for g = 1:numel(requiredGroups)
    groupName = char(requiredGroups(g));
    assert(numel(DEP.groups.(groupName).loadings) == nModality, ...
        'The number of modalities differs in group %s.', groupName);

    for m = 1:nModality
        X = DEP.groups.(groupName).loadings{m};
        assert(isnumeric(X) && ismatrix(X), ...
            'DEP.groups.%s.loadings{%d} must be a numeric matrix.', ...
            groupName, m);
        assert(size(X, 2) == nComponent, ...
            'The number of components differs in group %s, modality %d.', ...
            groupName, m);
    end
end

%% ----------------------- Check subject overlap ------------------------
% The four groups must be independent. Stop if any subject occurs in more
% than one group, because an independent two-sample test would be invalid.
for g1 = 1:(numel(requiredGroups) - 1)
    for g2 = (g1 + 1):numel(requiredGroups)
        name1 = char(requiredGroups(g1));
        name2 = char(requiredGroups(g2));
        ids1 = normalizeIDs(DEP.groups.(name1).matched_ids);
        ids2 = normalizeIDs(DEP.groups.(name2).matched_ids);
        duplicatedIDs = intersect(ids1, ids2);

        assert(isempty(duplicatedIDs), ...
            ['Groups %s and %s share %d subject IDs. The groups must be ' ...
             'made mutually exclusive before running independent tests.'], ...
            name1, name2, numel(duplicatedIDs));
    end
end

%% ------------------------ Welch t-tests -------------------------------
nComparison = numel(comparisonNames);
nTest = nComparison * nModality * nComponent;

comparison = strings(nTest, 1);
groupA = strings(nTest, 1);
groupB = strings(nTest, 1);
modality = strings(nTest, 1);
modalityIndex = zeros(nTest, 1);
component = zeros(nTest, 1);
nA = zeros(nTest, 1);
nB = zeros(nTest, 1);
meanA = nan(nTest, 1);
meanB = nan(nTest, 1);
sdA = nan(nTest, 1);
sdB = nan(nTest, 1);
meanDifference = nan(nTest, 1);
ciLower = nan(nTest, 1);
ciUpper = nan(nTest, 1);
tStatistic = nan(nTest, 1);
degreesOfFreedom = nan(nTest, 1);
pRaw = nan(nTest, 1);
hedgesG = nan(nTest, 1);
effectMagnitude = strings(nTest, 1);

row = 0;
for c = 1:nComparison
    nameA = char(comparisonGroupA(c));
    nameB = char(comparisonGroupB(c));

    for m = 1:nModality
        XA = DEP.groups.(nameA).loadings{m};
        XB = DEP.groups.(nameB).loadings{m};

        for k = 1:nComponent
            row = row + 1;

            x = XA(:, k);
            y = XB(:, k);
            x = x(isfinite(x));
            y = y(isfinite(y));

            comparison(row) = comparisonNames(c);
            groupA(row) = comparisonGroupA(c);
            groupB(row) = comparisonGroupB(c);
            modality(row) = modalityNames(m);
            modalityIndex(row) = m;
            component(row) = k;
            nA(row) = numel(x);
            nB(row) = numel(y);

            if numel(x) < 2 || numel(y) < 2
                effectMagnitude(row) = "not_estimable";
                continue;
            end

            meanA(row) = mean(x);
            meanB(row) = mean(y);
            sdA(row) = std(x, 0);
            sdB(row) = std(y, 0);
            meanDifference(row) = meanA(row) - meanB(row);

            % Two-sided Welch test: no equal-variance assumption.
            [~, pRaw(row), ci, stats] = ttest2( ...
                x, y, 'Vartype', 'unequal', 'Tail', 'both', ...
                'Alpha', alpha);

            ciLower(row) = ci(1);
            ciUpper(row) = ci(2);
            tStatistic(row) = stats.tstat;
            degreesOfFreedom(row) = stats.df;

            % Conventional Hedges' g for two independent groups.
            hedgesG(row) = calculateHedgesG(x, y);
            effectMagnitude(row) = labelEffect(abs(hedgesG(row)));
        end
    end
end

%% ---------------------- Multiple-comparison correction ----------------
% PRIMARY correction:
% Each modality and each planned group comparison is treated as a separate
% FDR family. Thus, when nComponent = 80, each FDR correction contains only
% the 80 component p-values from that specific modality/comparison.
qModalityComparison = nan(size(pRaw));
for c = 1:nComparison
    for m = 1:nModality
        idx = comparison == comparisonNames(c) & modalityIndex == m;
        qModalityComparison(idx) = bhFdr(pRaw(idx));
    end
end
significantModalityComparison = qModalityComparison < alpha;

% Secondary sensitivity value only: all tests corrected together.
% Do not use this column as the primary result for the present question.
qGlobalSecondary = bhFdr(pRaw);
significantGlobalSecondary = qGlobalSecondary < alpha;

results = table( ...
    comparison, groupA, groupB, modality, modalityIndex, component, ...
    nA, nB, meanA, meanB, sdA, sdB, meanDifference, ciLower, ciUpper, ...
    tStatistic, degreesOfFreedom, pRaw, qModalityComparison, ...
    significantModalityComparison, qGlobalSecondary, ...
    significantGlobalSecondary, hedgesG, ...
    effectMagnitude, ...
    'VariableNames', { ...
    'comparison', 'group_A', 'group_B', 'modality', 'modality_index', ...
    'component', 'n_A', 'n_B', 'mean_A', 'mean_B', 'sd_A', 'sd_B', ...
    'mean_difference_A_minus_B', 'CI95_lower', 'CI95_upper', ...
    't_statistic', 'degrees_of_freedom', 'p_raw', ...
    'q_FDR_modality_comparison', ...
    'significant_FDR_modality_comparison', ...
    'q_FDR_global_secondary', 'significant_FDR_global_secondary', ...
    'hedges_g', ...
    'effect_magnitude'});

% Primary significant results: FDR within each modality/comparison family.
significantResults = results( ...
    results.significant_FDR_modality_comparison, :);
if ~isempty(significantResults)
    significantResults.abs_hedges_g = abs(significantResults.hedges_g);
    significantResults = sortrows( ...
        significantResults, ...
        {'comparison', 'modality_index', ...
         'q_FDR_modality_comparison', 'abs_hedges_g'}, ...
        {'ascend', 'ascend', 'ascend', 'descend'});
end

% A second ranking table is useful when the question is "which components
% differ most?" Statistical significance is retained, then |g| is ranked.
rankedByEffect = results( ...
    results.significant_FDR_modality_comparison, :);
if ~isempty(rankedByEffect)
    rankedByEffect.abs_hedges_g = abs(rankedByEffect.hedges_g);
    rankedByEffect = sortrows( ...
        rankedByEffect, ...
        {'abs_hedges_g', 'q_FDR_modality_comparison'}, ...
        {'descend', 'ascend'});
end

% Count significant components separately for all 9 FDR families.
summaryComparison = strings(nComparison * nModality, 1);
summaryModality = strings(nComparison * nModality, 1);
summaryNTests = zeros(nComparison * nModality, 1);
summaryNSignificant = zeros(nComparison * nModality, 1);
summaryRow = 0;
for c = 1:nComparison
    for m = 1:nModality
        summaryRow = summaryRow + 1;
        idx = comparison == comparisonNames(c) & modalityIndex == m;
        summaryComparison(summaryRow) = comparisonNames(c);
        summaryModality(summaryRow) = modalityNames(m);
        summaryNTests(summaryRow) = nnz(idx);
        summaryNSignificant(summaryRow) = ...
            nnz(significantModalityComparison(idx));
    end
end
familySummary = table(summaryComparison, summaryModality, ...
    summaryNTests, summaryNSignificant, ...
    'VariableNames', {'comparison', 'modality', ...
                      'n_component_tests', 'n_FDR_significant'});

%% --------------------------- Save outputs ------------------------------
analysisInfo = struct();
analysisInfo.input_file = inputFile;
analysisInfo.created = char(datetime('now', 'Format', 'yyyy-MM-dd HH:mm:ss'));
analysisInfo.test = 'Two-sided Welch independent-samples t-test';
analysisInfo.primary_FDR_family = ...
    ['Separate BH-FDR family for each modality x planned comparison; ' ...
     'each family contains all component tests for that modality/comparison'];
analysisInfo.alpha = alpha;
analysisInfo.n_modalities = nModality;
analysisInfo.n_components = nComponent;
analysisInfo.n_comparisons = nComparison;
analysisInfo.n_tests = nTest;
analysisInfo.effect_size = ...
    'Conventional Hedges g based on pooled SD; sign is group A minus group B.';
analysisInfo.covariates = ...
    'None. This script performs unadjusted group comparisons.';

save(outputMat, 'results', 'significantResults', 'rankedByEffect', ...
    'familySummary', 'analysisInfo', '-v7.3');

% Start a clean workbook so sheets left by an earlier analysis version do
% not remain and cause confusion.
if isfile(outputXlsx)
    delete(outputXlsx);
end

writetable(results, outputXlsx, 'Sheet', 'all_tests');
writetable(significantResults, outputXlsx, ...
    'Sheet', 'FDR_by_modality_significant');
writetable(rankedByEffect, outputXlsx, 'Sheet', 'ranked_by_abs_g');
writetable(familySummary, outputXlsx, 'Sheet', 'FDR_family_summary');

% Nine easy-to-read sheets: one for each modality x group comparison.
shortComparisonNames = ["noMin_vs_mild", "mild_vs_mod", "mod_vs_high"];
for c = 1:nComparison
    for m = 1:nModality
        idx = comparison == comparisonNames(c) & modalityIndex == m;
        oneFamily = results(idx, :);
        oneFamily = sortrows(oneFamily, ...
            {'q_FDR_modality_comparison', 'component'}, ...
            {'ascend', 'ascend'});

        sheetName = modalityNames(m) + "_" + shortComparisonNames(c);
        writetable(oneFamily, outputXlsx, 'Sheet', char(sheetName));
    end
end

fprintf('\nNumber of tests: %d\n', height(results));
fprintf(['Primary FDR-significant tests, correcting 80 components within ' ...
         'each modality/comparison (q < %.3f): %d\n'], ...
    alpha, height(significantResults));
fprintf('MAT output:\n%s\n', outputMat);
fprintf('Excel output:\n%s\n', outputXlsx);

if ~isempty(rankedByEffect)
    disp('FDR results for each modality/comparison family:');
    disp(familySummary);
    disp('Top primary FDR-significant results ranked by absolute Hedges g:');
    disp(rankedByEffect(1:min(20, height(rankedByEffect)), ...
        {'comparison', 'modality', 'component', ...
         'mean_difference_A_minus_B', 'p_raw', ...
         'q_FDR_modality_comparison', 'hedges_g', ...
         'effect_magnitude'}));
else
    disp('FDR results for each modality/comparison family:');
    disp(familySummary);
    disp(['No tests survived BH-FDR correction within their respective ' ...
          'modality/comparison families.']);
end

%% --------------------------- Local functions ---------------------------
function ids = normalizeIDs(ids)
    ids = lower(strip(string(ids)));
    ids = ids(~ismissing(ids) & ids ~= "");
end

function g = calculateHedgesG(x, y)
    n1 = numel(x);
    n2 = numel(y);
    df = n1 + n2 - 2;

    if n1 < 2 || n2 < 2 || df <= 0
        g = NaN;
        return;
    end

    s1 = std(x, 0);
    s2 = std(y, 0);
    pooledSD = sqrt(((n1 - 1) * s1^2 + (n2 - 1) * s2^2) / df);

    if pooledSD == 0 || ~isfinite(pooledSD)
        g = NaN;
        return;
    end

    cohensD = (mean(x) - mean(y)) / pooledSD;

    % Small-sample bias correction. With the current sample sizes this is
    % close to 1, but retaining it gives conventional Hedges' g.
    correctionJ = 1 - 3 / (4 * (n1 + n2) - 9);
    g = correctionJ * cohensD;
end

function label = labelEffect(absG)
    if ~isfinite(absG)
        label = "not_estimable";
    elseif absG < 0.2
        label = "negligible";
    elseif absG < 0.5
        label = "small";
    elseif absG < 0.8
        label = "medium";
    else
        label = "large";
    end
end

function q = bhFdr(p)
    % Benjamini-Hochberg adjusted p-values without requiring an additional
    % toolbox. NaN p-values remain NaN.
    q = nan(size(p));
    valid = isfinite(p);
    pv = p(valid);

    if isempty(pv)
        return;
    end

    [sortedP, order] = sort(pv(:), 'ascend');
    m = numel(sortedP);
    adjusted = sortedP .* m ./ (1:m)';
    adjusted = flipud(cummin(flipud(adjusted)));
    adjusted = min(adjusted, 1);

    unsorted = nan(m, 1);
    unsorted(order) = adjusted;
    q(valid) = unsorted;
end
